const GAME_JOIN_PORT_OVERRIDE: Partial<Record<GameFamily, { port: number; protocol: "tcp" | "udp" }>> = {
  rust: { port: 28015, protocol: "udp" }, // GAME_PORT is 28016/tcp rcon
  ark: { port: 7777, protocol: "udp" }, // GAME_PORT is 27020/tcp rcon
  projectzomboid: { port: 16261, protocol: "udp" }, // GAME_PORT is 27015/tcp rcon
  factorio: { port: 34197, protocol: "udp" }, // GAME_PORT is 27015/tcp rcon
  arkasa: { port: 7777, protocol: "udp" }, // GAME_PORT is 27020/tcp rcon
  // (soulmask needs no entry any more: its GAME_PORT is now 8777/udp — the port
  //  players join on — because its 18888/tcp admin port turned out to be bound
  //  to loopback inside the container and unreachable. See GAME_PORT.)
  squad: { port: 7787, protocol: "udp" }, // GAME_PORT is 21114/tcp rcon
  kf2: { port: 7777, protocol: "udp" }, // GAME_PORT is 8080/tcp webadmin
  // Source-engine families: srcds binds the SAME port number on both protocols,
  // and the two are different services. UDP 27015 is the game + A2S query
  // protocol players and server browsers speak; TCP 27015 is RCON. Proven live
  // on a running Garry's Mod server 2026-09-07 — an A2S_INFO datagram to UDP
  // 27015 answered `ff ff ff ff 41 …` (S2C_CHALLENGE), while TCP 27015 accepted
  // the connection and returned nothing at all to the same query. Because the
  // port NUMBERS match, this one hid where the others didn't: the forward looked
  // right and was on the wrong protocol, so players could not connect AND the
  // single port left published to the internet was RCON — the exact exposure
  // `196e5c9` was written to end.
  gmod: { port: 27015, protocol: "udp" }, // GAME_PORT is 27015/tcp rcon
  // 7 Days to Die is the same shape as the Source families above — it binds
  // 26900 on BOTH protocols and only the UDP one carries the game. Verified
  // live 2026-09-07: the server's own log says `[NET] Disabling protocol:
  // SteamNetworking` then `NET: LiteNetLib server started`, and LiteNetLib is
  // UDP-only; an A2S_INFO datagram to udp:26900 answered `ff ff ff ff 41 …`
  // (S2C_CHALLENGE) while tcp:26900 accepted the connection and replied with
  // four unrelated ASCII bytes. Matching port numbers hid this exactly the way
  // they hid it for Garry's Mod.
  sdtd: { port: 26900, protocol: "udp" }, // GAME_PORT is 26900/tcp
  tf2: { port: 27015, protocol: "udp" }, // GAME_PORT is 27015/tcp rcon
  l4d2: { port: 27015, protocol: "udp" }, // GAME_PORT is 27015/tcp rcon
  cs2: { port: 27015, protocol: "udp" }, // GAME_PORT is 27015/tcp rcon
  // (unturned needs no entry: its GAME_PORT is already 27015/udp — the same port
  //  players join on — because Unturned binds no TCP port at all. See GAME_PORT.)
};

/**
 * The port a player's game client actually connects to for this family — the
 * one that must be port-forwarded for a NAT server and shown to the customer as
 * their connect address. Identical to {@link GAME_PORT} for every family except
 * the eight in `GAME_JOIN_PORT_OVERRIDE`.
 */
export function joinPortFor(family: GameFamily): { port: number; protocol: "tcp" | "udp" } {
  return GAME_JOIN_PORT_OVERRIDE[family] ?? GAME_PORT[family];
}

/**
 * ADDITIONAL ports (beyond {@link joinPortFor}'s single port) a family needs
 * forwarded to actually be joinable — not more admin/RCON exposure, genuine
 * extra game-protocol ports. Found live 2026-09-08: Valheim's dedicated
 * server opens THREE consecutive UDP ports for its Steam networking layer
 * (base + query + a third), confirmed live against a real customer server —
 * with only the base port (2456) forwarded, the client got a hard "Failed to
 * connect" before ever reaching a password prompt. `worker/index.ts`'s NAT
 * auto-forward only ever created one PortForward row per server before this,
 * so every NAT Valheim order needed the customer to manually discover and add
 * the missing two — exactly the mistake that produced that ticket.
 *
 * Sourced from each family's own `docker run -p ...` mapping (prisma/
 * catalog.ts / seed-wave*-games.ts), same provenance discipline as
 * `GAME_JOIN_PORT_OVERRIDE` above — never guessed.
 *
 * DELIBERATELY INCOMPLETE: several other families also publish a port RANGE
 * in their setup script (gmod/conan/unturned/theforest/factorio: 27015-27017;
 * eco/empyrion/theisle/stationeers: 27015-27016 or 30000-30003) and may need
 * the same treatment — NOT added here without individually verifying each one
 * live first (a wrong guess here creates the same class of bug this table
 * exists to fix). See the 2026-09-06 game-catalog verify sweep for the
 * methodology; extend this table only after that same live verification.
 */
const GAME_EXTRA_JOIN_PORTS: Partial<Record<GameFamily, { port: number; protocol: "tcp" | "udp" }[]>> = {
  valheim: [
    { port: 2457, protocol: "udp" },
    { port: 2458, protocol: "udp" },
  ],
};

